// Execute runs the root command and returns any error.
// [🧰repo⌨️cli💻maingo🔖cliadapter🛠️execute](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/d/i/Execute)
func Execute(factory EngineFactory) error {
