// summarizeCommand MUST return a summary for the given entity ID.
// [🧰repo⌨️cli💻maingo🔖cliadapter🛠️summarizecommand](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/d/i/summarizeCommand)
func summarizeCommand(factory EngineFactory, config *Config) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "summarize <id>",
		Short: "Summarize an entity by its ID",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			id := args[0]
			buildOpts := TreeBuildOptions{
				IncludeSections: true,
			}
			tree := BuildMonorepoTreeCached(ctx, buildOpts)
			var found *TreeNode
			var findByID func(node *TreeNode)
			findByID = func(node *TreeNode) {
				if found != nil {
					return
				}
				if node.ID == id {
					found = node
					return
				}
				for _, c := range node.Children {
					findByID(c)
				}
			}
			findByID(tree)
			if found == nil {
				return fmt.Errorf("entity not found: %s", id)
			}
			type summaryOutput struct {
				ID      string `json:"id"`
				Kind    string `json:"kind"`
				Label   string `json:"label"`
				Summary string `json:"summary"`
				URI     string `json:"uri"`
			}
			out := summaryOutput{
				ID:      found.ID,
				Kind:    string(found.Kind),
				Label:   found.Label,
				Summary: found.Summary,
				URI:     found.URI,
			}
			switch {
			case config.IsJSON():
				encoded, err := json.Marshal(out)
				if err != nil {
					return err
				}
				fmt.Fprintln(cmd.OutOrStdout(), string(encoded))
			default:
				fmt.Fprintf(cmd.OutOrStdout(), "[%s] %s\n", out.Kind, out.Label)
				if out.Summary != "" {
					fmt.Fprintf(cmd.OutOrStdout(), "  %s\n", out.Summary)
				}
				if out.URI != "" {
					fmt.Fprintf(cmd.OutOrStdout(), "  %s\n", out.URI)
				}
			}
			return nil
		},
	}
	return cmd
}

