// HasOnlyKinds MUST return true only when the property is present.
// HasOnlyKinds reports whether the TreeFilter has only kinds.
// [🧰repo⌨️cli💻maingo🔖cliadapter🔖models🔖monorepotreetypes🛠️hasonlykinds](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Models/s/Monorepo%20Tree%20Types/d/i/HasOnlyKinds)
func (f *TreeFilter) HasOnlyKinds() bool {
	return len(f.OnlyKinds) > 0
}

// IsKindVisible MUST return true only when the condition is met.
// IsKindVisible reports whether the TreeFilter is kind visible.
// [🧰repo⌨️cli💻maingo🔖cliadapter🔖models🔖monorepotreetypes🛠️iskindvisible](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Models/s/Monorepo%20Tree%20Types/d/i/IsKindVisible)
func (f *TreeFilter) IsKindVisible(kind TreeNodeKind) bool {
	if kind == TreeNodeCategory {
		return true
	}
	if f.HasOnlyKinds() {
		return f.OnlyKinds[kind]
	}
	return !f.ExcludeKinds[kind]
}

// MatchesSubKind MUST operate on the TreeFilter receiver and return consistent results.
// MatchesSubKind performs the matches sub kind operation on the TreeFilter.
// [🧰repo⌨️cli💻maingo🔖cliadapter🔖models🔖monorepotreetypes🛠️matchessubkind](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Models/s/Monorepo%20Tree%20Types/d/i/MatchesSubKind)
func (f *TreeFilter) MatchesSubKind(kind TreeNodeKind, subKind string) bool {
	if subKind == "" {
		return true
	}
	if only, ok := f.OnlySubKinds[kind]; ok && len(only) > 0 {
		for _, s := range only {
			if strings.EqualFold(s, subKind) {
				return true
			}
		}
		return false
	}
	if exclude, ok := f.ExcludeSubKinds[kind]; ok {
		for _, s := range exclude {
			if strings.EqualFold(s, subKind) {
				return false
			}
		}
	}
	return true
}

// MatchesDate MUST operate on the TreeFilter receiver and return consistent results.
// MatchesDate performs the matches date operation on the TreeFilter.
// [🧰repo⌨️cli💻maingo🔖cliadapter🔖models🔖monorepotreetypes🛠️matchesdate](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Models/s/Monorepo%20Tree%20Types/d/i/MatchesDate)
func (f *TreeFilter) MatchesDate(year, month, day int) bool {
	if len(f.OnlyYears) > 0 {
		found := false
		for _, y := range f.OnlyYears {
			if y == year {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	for _, y := range f.ExcludeYears {
		if y == year {
			return false
		}
	}
	if len(f.OnlyMonths) > 0 && month > 0 {
		found := false
		for _, m := range f.OnlyMonths {
			if m == month {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	for _, m := range f.ExcludeMonths {
		if m == month {
			return false
		}
	}
	if len(f.OnlyDays) > 0 && day > 0 {
		found := false
		for _, d := range f.OnlyDays {
			if d == day {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	for _, d := range f.ExcludeDays {
		if d == day {
			return false
		}
	}
	return true
}

// MatchesStatus MUST operate on the TreeFilter receiver and return consistent results.
// MatchesStatus performs the matches status operation on the TreeFilter.
// [🧰repo⌨️cli💻maingo🔖cliadapter🔖models🔖monorepotreetypes🛠️matchesstatus](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Models/s/Monorepo%20Tree%20Types/d/i/MatchesStatus)
func (f *TreeFilter) MatchesStatus(status string) bool {
	if f.OnlyStatus == "" {
		return true
	}
	return strings.EqualFold(f.OnlyStatus, status)
}

// MatchesContributor MUST operate on the TreeFilter receiver and return consistent results.
// MatchesContributor performs the matches contributor operation on the TreeFilter.
// [🧰repo⌨️cli💻maingo🔖cliadapter🔖models🔖monorepotreetypes🛠️matchescontributor](repo://p/i/repo/b/b/cli/f/main.go/s/Cli%20Adapter/s/Models/s/Monorepo%20Tree%20Types/d/i/MatchesContributor)
func (f *TreeFilter) MatchesContributor(contributor string) bool {
	if len(f.OnlyContributors) > 0 {
		for _, c := range f.OnlyContributors {
			if strings.EqualFold(c, contributor) {
				return true
			}
		}
		return false
	}
	for _, c := range f.ExcludeContributors {
		if strings.EqualFold(c, contributor) {
			return false
		}
	}
	return true
}

