// FormatHeader MUST produce a well-formed header string.
// FormatHeader formats the header into its string representation.
// [🧰repo⌨️cli💻maingo🔖types🔖languages🛠️formatheader](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Languages/d/i/FormatHeader)
func (l *BaseLanguage) FormatHeader(fileId, fileUri, summary, contributors, license, requirements string) string {
	if !l.supportsHeaders {
		return ""
	}
	cp := l.commentPrefix
	var b strings.Builder
	b.WriteString(l.FormatSectionStart("Header"))
	b.WriteString("\n")
	b.WriteString(cp + " [" + fileId + "](" + fileUri + ")\n")
	for _, line := range strings.Split(contributors, "\n") {
		if strings.TrimSpace(line) != "" {
			b.WriteString(cp + " " + line + "\n")
		}
	}
	b.WriteString("\n")
	for _, line := range strings.Split(license, "\n") {
		if line == "" {
			b.WriteString(cp + "\n")
		} else {
			b.WriteString(cp + " " + line + "\n")
		}
	}
	b.WriteString("\n")
	if summary != "" {
		for _, line := range strings.Split(summary, "\n") {
			if line == "" {
				b.WriteString(cp + "\n")
			} else {
				b.WriteString(cp + " " + line + "\n")
			}
		}
		b.WriteString("\n")
	}
	if requirements != "" {
		for _, line := range strings.Split(requirements, "\n") {
			if line == "" {
				b.WriteString(cp + "\n")
			} else {
				b.WriteString(cp + " " + line + "\n")
			}
		}
		b.WriteString("\n")
	}
	b.WriteString(l.FormatSectionEnd("Header"))
	b.WriteString("\n")
	return b.String()
}

// PolicySectionStartMatch MUST operate on the BaseLanguage receiver and return consistent results.
// PolicySectionStartMatch performs the policy section start match operation on the BaseLanguage.
// [🧰repo⌨️cli💻maingo🔖types🔖languages🛠️policysectionstartmatch](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Languages/d/i/PolicySectionStartMatch)
func (l *BaseLanguage) PolicySectionStartMatch(line string) (bool, string) {
	if l.policySectionStart == nil {
		return false, ""
	}
	match := l.policySectionStart.FindStringSubmatch(line)
	if match == nil {
		return false, ""
	}
	name := ""
	if len(match) > 1 {
		name = strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(match[1]), "🔖"))
	}
	return true, name
}

// PolicySectionEndMatch MUST operate on the BaseLanguage receiver and return consistent results.
// PolicySectionEndMatch performs the policy section end match operation on the BaseLanguage.
// [🧰repo⌨️cli💻maingo🔖types🔖languages🛠️policysectionendmatch](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Languages/d/i/PolicySectionEndMatch)
func (l *BaseLanguage) PolicySectionEndMatch(line string) (bool, string) {
	if l.policySectionEnd == nil {
		return false, ""
	}
	match := l.policySectionEnd.FindStringSubmatch(line)
	if match == nil {
		return false, ""
	}
	name := ""
	if len(match) > 1 {
		name = strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(match[1]), "🔖"))
	}
	return true, name
