// LoadGitignore MUST read from the configured storage path.
// LoadGitignore loads the gitignore from storage.
// [🧰repo⌨️cli💻maingo🔖types🔖utils🛠️loadgitignore](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Utils/d/i/LoadGitignore)
func LoadGitignore(cwd string) ([]string, error) {
	gitignorePath := filepath.Join(cwd, ".gitignore")
	if !FileExists(gitignorePath) {
		return nil, nil
	}
	content, err := ReadTextFile(gitignorePath)
	if err != nil {
		return nil, err
	}
	var patterns []string
	for _, line := range strings.Split(content, "\n") {
		line = strings.TrimSpace(line)
		if line != "" && !strings.HasPrefix(line, "#") {
			patterns = append(patterns, line)
		}
	}
	return patterns, nil
}

func matchesIgnorePattern(path string, isDir bool, pattern string) bool {
	pattern = NormalizePath(strings.TrimSpace(pattern))
	if pattern == "" {
		return false
	}
	path = NormalizePath(strings.TrimSpace(path))
	if path == "" {
		return false
	}
	candidates := []string{path}
	if isDir && !strings.HasSuffix(path, "/") {
		candidates = append(candidates, path+"/")
	}
	patterns := []string{pattern}
	if strings.HasSuffix(pattern, "/**") {
		base := strings.TrimSuffix(pattern, "/**")
		if base != "" {
			patterns = append(patterns, base, base+"/")
		}
	}
	for _, candidatePattern := range patterns {
		if candidatePattern == "" {
			continue
		}
		for _, candidatePath := range candidates {
			if matched, _ := doublestar.Match(candidatePattern, candidatePath); matched {
				return true
			}
		}
	}
	return false
}

// SimpleGlob MUST complete the operation and return consistent results.
// SimpleGlob performs the simple glob operation.
// [🧰repo⌨️cli💻maingo🔖types🔖utils🛠️simpleglob](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Utils/d/i/SimpleGlob)
func SimpleGlob(pattern string, cwd string, ignorePatterns []string, respectGitignore bool) ([]string, error) {
	if cwd == "" {
		cwd = rootDir
	}
	var gitignorePatterns []string
	if respectGitignore {
		var err error
		gitignorePatterns, err = LoadGitignore(cwd)
		if err != nil {
			return nil, err
		}
	}
	allIgnore := append(ignorePatterns, gitignorePatterns...)
	var files []string
	absPattern := filepath.Join(cwd, pattern)
	matches, err := doublestar.FilepathGlob(absPattern)
	if err != nil {
		return nil, err
	}
	for _, match := range matches {
		rel, err := filepath.Rel(cwd, match)
		if err != nil {
			continue
		}
		relNorm := NormalizePath(rel)
		ignored := false
		for _, ig := range allIgnore {
			if matchesIgnorePattern(relNorm, false, ig) {
				ignored = true
				break
			}
		}
		if !ignored {
			files = append(files, relNorm)
		}
	}
	return files, nil
}

func globByExtension(root string, patternBase string, exts []string, ignorePatterns []string, respectGitignore bool) ([]string, error) {
	base := strings.TrimSuffix(patternBase, "/**/*")
	if patternBase == "**/*" {
		base = ""
	}
	absBase := filepath.Join(root, base)
	info, err := os.Stat(absBase)
	if err != nil || !info.IsDir() {
		return nil, nil
	}
	gitignorePatterns := []string{}
	if respectGitignore {
		gitignorePatterns, err = LoadGitignore(root)
		if err != nil {
			return nil, err
		}
	}
	allIgnore := append(ignorePatterns, gitignorePatterns...)
	allowed := make(map[string]struct{}, len(exts))
	for _, ext := range exts {
		allowed[strings.ToLower(ext)] = struct{}{}
	}
	results := make([]string, 0)
	err = filepath.WalkDir(absBase, func(path string, d os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		name := d.Name()
		if d.IsDir() && strings.HasPrefix(name, ".") {
			return filepath.SkipDir
		}
		rel, relErr := filepath.Rel(root, path)
		if relErr != nil {
			return nil
		}
		rel = strings.TrimPrefix(NormalizePath(rel), "./")
		if rel == "" || rel == "." {
			return nil
		}
		for _, ig := range allIgnore {
			if matchesIgnorePattern(rel, d.IsDir(), ig) {
				if d.IsDir() {
					return filepath.SkipDir
				}
				return nil
			}
		}
		if d.IsDir() {
			return nil
		}
		ext := strings.TrimPrefix(strings.ToLower(filepath.Ext(rel)), ".")
		if _, ok := allowed[ext]; !ok {
			return nil
		}
		results = append(results, rel)
		return nil
	})
	if err != nil {
		return nil, err
	}
	return results, nil
}

