// ListDirEntries returns all available dir entries entries.
// [🧰repo⌨️cli💻maingo🔖types🔖utils🛠️listdirentries](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Utils/d/i/ListDirEntries)
func ListDirEntries(dir string, dirsOnly bool) ([]string, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, e := range entries {
		if strings.HasPrefix(e.Name(), ".") {
			continue
		}
		if dirsOnly && !e.IsDir() {
			continue
		}
		if !dirsOnly && e.IsDir() {
			continue
		}
		names = append(names, e.Name())
	}
	return names, nil
}

// WalkDir MUST visit every entry and MUST stop when the callback returns an error.
// WalkDir recursively walks the dir and invokes the callback.
// [🧰repo⌨️cli💻maingo🔖types🔖utils🛠️walkdir](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Utils/d/i/WalkDir)
func WalkDir(dir string, fn func(path string, isDir bool) error) error {
	return filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if strings.HasPrefix(info.Name(), ".") {
			if info.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		return fn(path, info.IsDir())
	})
}

// ParseScope MUST return an error when the input is malformed.
// ParseScope parses the input and returns the scope result.
// [🧰repo⌨️cli💻maingo🔖types🔖utils🛠️parsescope](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Utils/d/i/ParseScope)
func ParseScope(raw string) Scope {
	if raw == "" || raw == "compose" {
		return Scope{Raw: "compose", Kind: ScopeRepo}
	}
	if strings.Contains(raw, "§") {
		parts := strings.SplitN(raw, "§", 2)
		return Scope{Raw: raw, Kind: ScopeDefinition, FilePath: parts[0], DefinitionName: parts[1]}
	}
	if strings.Contains(raw, "#") {
		parts := strings.Split(raw, "#")
		return Scope{Raw: raw, Kind: ScopeSection, FilePath: parts[0], SectionPath: parts[1:]}
	}
	ext := strings.ToLower(filepath.Ext(raw))
	codeExtensions := map[string]bool{".ts": true, ".tsx": true, ".js": true, ".jsx": true, ".py": true, ".cs": true, ".go": true, ".json": true, ".md": true, ".yaml": true, ".yml": true, ".sql": true, ".graphql": true}
	if codeExtensions[ext] {
		return Scope{Raw: raw, Kind: ScopeFile, FilePath: raw}
	}
	if strings.HasPrefix(raw, "compose/") {
		return Scope{Raw: raw, Kind: ScopeTechnology, TechnologyName: raw}
	}
	if strings.HasSuffix(raw, "/") {
		return Scope{Raw: raw, Kind: ScopeFolder, FilePath: raw}
	}
	return Scope{Raw: raw, Kind: ScopeFolder, FilePath: raw}
}

