	for _, v := range ctx.Breachs {
		parts := strings.Split(string(v.Kind), "/")
		if len(parts) > 0 {
			policyID := parts[0]
			breachsByPolicy[policyID] = append(breachsByPolicy[policyID], v)
		}
	}

	for _, policy := range ctx.Policies {
		var breachs []PolicyBreachRef
		for _, v := range breachsByPolicy[policy.ID] {
			info := v.Kind.Info()
			breachs = append(breachs, PolicyBreachRef{
				Kind:        v.Kind,
				Priority:    info.Priority,
				Autofixable: info.Autofixable,
				Solution:    info.Solution,
			})
		}
		result = append(result, CodebasePolicy{
			ID:      policy.ID,
			Name:    policy.Name,
			Scopes:  policy.Scopes,
			Breachs: breachs,
		})
	}
	return result
}

// BuildCodebaseBreachs MUST assemble the codebase breachs from the available context data.
// BuildCodebaseBreachs constructs and returns the codebase breachs structure.
// [🧰repo⌨️cli💻maingo🔖types🔖codebase🛠️buildcodebasebreachs](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Codebase/d/i/BuildCodebaseBreachs)
func BuildCodebaseBreachs(ctx *CodebaseContext) []CodebaseBreach {
	var result []CodebaseBreach

	for i, v := range ctx.Breachs {
		filePath := extractFilePath(v.Scope)
		bundleName := ctx.GetBundleForFile(filePath)
		info := v.Kind.Info()

		breachID := fmt.Sprintf("%s#|%s|%s#%d", v.Kind, bundleName, filePath, i)

		var folders []BreachFolder
		if filePath != "" {
			folder := NormalizePath(filepath.Dir(filePath))
			if folder != "." {
				folderID := folder
				if bundleName != "" {
					folderID = bundleName + "/" + folder
				}
				folders = append(folders, BreachFolder{
					ID:   folderID,
					Path: folder,
					URI:  ctx.FolderURI(folder),
				})
			}
		}

		var files []BreachFile
		if filePath != "" {
			fileID := filePath
			if bundleName != "" {
				fileID = bundleName + "/" + filepath.Base(filePath)
			}
			files = append(files, BreachFile{
				ID:   fileID,
				Path: filePath,
				URI:  ctx.FileURI(filePath),
				Range: &FileRange{
					Start: RangePosition{Line: v.Line, Column: v.Column},
					End:   RangePosition{Line: v.Line, Column: v.Column},
				},
			})
		}

		result = append(result, CodebaseBreach{
			ID:          breachID,
			Folders:     folders,
			Files:       files,
			Kind:        v.Kind,
			Priority:    info.Priority,
			Autofixable: info.Autofixable,
			Reason:      info.Reason,
			Solution:    info.Solution,
		})
	}
	return result
}

// BuildCodebaseTree MUST assemble the codebase tree from the available context data.
// BuildCodebaseTree constructs and returns the codebase tree structure.
// [🧰repo⌨️cli💻maingo🔖types🔖codebase🛠️buildcodebasetree](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Codebase/d/i/BuildCodebaseTree)
func BuildCodebaseTree(ctx *CodebaseContext, bundles []CodebaseBundle, files []CodebaseFile, sections []CodebaseSection, definitions []CodebaseDefinition) map[string]*CbTreeNode {
	tree := make(map[string]*CbTreeNode)
	tree["compose"] = &CbTreeNode{Kind: CbTreeNodeRepo, Children: make(map[string]*CbTreeNode)}
	root := tree["compose"]

	for _, bundle := range bundles {
		root.Children[bundle.ID] = &CbTreeNode{Kind: CbTreeNodeBundle, Children: make(map[string]*CbTreeNode)}
	}

	folderNodes := make(map[string]*CbTreeNode)
	for _, file := range files {
		bundleName := ctx.GetBundleForFile(file.Path)
		var parent *CbTreeNode
		if bundleName != "" {
			parent = root.Children[bundleName]
		} else {
			parent = root
		}
		folder := NormalizePath(filepath.Dir(file.Path))
		if folder != "." {
			parts := strings.Split(folder, "/")
			for i, part := range parts {
				folderPath := strings.Join(parts[:i+1], "/")
				if _, ok := folderNodes[folderPath]; !ok {
					folderNode := &CbTreeNode{Kind: CbTreeNodeFolder, Children: make(map[string]*CbTreeNode)}
					if i == 0 {
						parent.Children[part] = folderNode
					} else {
						parentPath := strings.Join(parts[:i], "/")
						folderNodes[parentPath].Children[part] = folderNode
					}
					folderNodes[folderPath] = folderNode
				}
			}
			fileNode := &CbTreeNode{Kind: CbTreeNodeFile, Children: make(map[string]*CbTreeNode)}
			folderNodes[folder].Children[file.ID] = fileNode
		} else {
			fileNode := &CbTreeNode{Kind: CbTreeNodeFile, Children: make(map[string]*CbTreeNode)}
			parent.Children[file.ID] = fileNode
		}
	}

	return tree
}

// BuildCodebase MUST assemble the codebase from the available context data.
// BuildCodebase constructs and returns the codebase structure.
// [🧰repo⌨️cli💻maingo🔖types🔖codebase🛠️buildcodebase](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Codebase/d/i/BuildCodebase)
func BuildCodebase(ctx *CodebaseContext) *Codebase {
	bundles := BuildCodebaseBundles(ctx)
	folders := BuildCodebaseFolders(ctx)
	files := BuildCodebaseFiles(ctx)
	sections := BuildCodebaseSections(ctx)
	definitions := BuildCodebaseDefinitions(ctx)
	contributors := BuildCodebaseContributors(ctx)
	tickets := BuildCodebaseTickets(ctx)
	policies := BuildCodebasePolicies(ctx)
	breachs := BuildCodebaseBreachs(ctx)
	tree := BuildCodebaseTree(ctx, bundles, files, sections, definitions)

	return &Codebase{
		Bundles:      bundles,
		Folders:      folders,
		Files:        files,
		Sections:     sections,
		Definitions:  definitions,
		Contributors: contributors,
		Tickets:      tickets,
		Policies:     policies,
		Breachs:      breachs,
		Tree:         tree,
	}
}

// BuildCodebaseSnapshot MUST assemble the codebase snapshot from the available context data.
// BuildCodebaseSnapshot constructs and returns the codebase snapshot structure.
// [🧰repo⌨️cli💻maingo🔖types🔖codebase🛠️buildcodebasesnapshot](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Codebase/d/i/BuildCodebaseSnapshot)
func BuildCodebaseSnapshot(files []string, bundles []Bundle, checkpoint string) (*Codebase, error) {
	ctx := &CodebaseContext{RootDir: rootDir, RootURI: "file://" + NormalizePath(rootDir)}
	ctx.Bundles = bundles
	ctx.Files = files
	ctx.Policies = GetPolicies()
	codebase := &Codebase{}
	codebase.Bundles = BuildCodebaseBundlesForFiles(ctx, checkpoint)
	codebase.Folders = BuildCodebaseFoldersForFiles(ctx, checkpoint)
	codebase.Files = BuildCodebaseFilesForFiles(ctx, checkpoint)
	codebase.Sections = BuildCodebaseSectionsForFiles(ctx, checkpoint)
	codebase.Definitions = BuildCodebaseDefinitionsForFiles(ctx, checkpoint)
	codebase.Tree = BuildCodebaseTree(ctx, codebase.Bundles, codebase.Files, codebase.Sections, codebase.Definitions)
	return codebase, nil
}

// BuildCodebaseBundlesForFiles MUST assemble the codebase bundles for files from the available context data.
// BuildCodebaseBundlesForFiles constructs and returns the codebase bundles for files structure.
// [🧰repo⌨️cli💻maingo🔖types🔖codebase🛠️buildcodebasebundlesforfiles](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Codebase/d/i/BuildCodebaseBundlesForFiles)
func BuildCodebaseBundlesForFiles(ctx *CodebaseContext, checkpoint string) []CodebaseBundle {
	var result []CodebaseBundle
	fileCounts := make(map[string]int)
	lineCounts := make(map[string]int)
	sectionCounts := make(map[string]int)
	definitionCounts := make(map[string]int)
	folderSets := make(map[string]map[string]struct{})

	for _, bundle := range ctx.Bundles {
		name := normalizeBundleLabel(bundle.Name)
		folderSets[name] = make(map[string]struct{})
	}

	if _, ok := folderSets["repo/repo"]; !ok {
		folderSets["repo/repo"] = make(map[string]struct{})
	}

	for _, file := range ctx.Files {
		bundleName := ctx.GetBundleForFile(file)
		if bundleName == "" {
			continue
		}
		fileCounts[bundleName]++
		folder := NormalizePath(filepath.Dir(file))
		if folder != "." {
			folderSets[bundleName][folder] = struct{}{}
		}
		content, err := ReadTextFileAtCheckpoint(checkpoint, file)
		if err != nil {
			continue
		}
		lineCounts[bundleName] += CountLines(content)
		sections := ParseSections(content, file)
		sectionCounts[bundleName] += countSections(sections)
		lang := GetLanguage(file)
		if lang != nil && lang.SupportsDefinitions() {
			lines := strings.Split(content, "\n")
			defs := lang.ParseDefinitions(content, lines)
			definitionCounts[bundleName] += len(defs)
		}
	}

	var bundleNames []string
	for name := range folderSets {
		bundleNames = append(bundleNames, name)
	}
	sort.Strings(bundleNames)

	for _, name := range bundleNames {
		bundleRoot := ""
		for _, b := range ctx.Bundles {
			if normalizeBundleLabel(b.Name) == name {
				bundleRoot = b.Root
				break
			}
		}

		result = append(result, CodebaseBundle{
			ID:     name,
			Folder: bundleRoot,
			URI:    ctx.FileURI(bundleRoot),
			Metrics: &BundleMetricsInternal{
				Folders:     len(folderSets[name]),
				Files:       fileCounts[name],
				Sections:    sectionCounts[name],
				Definitions: definitionCounts[name],
				Lines:       lineCounts[name],
			},
		})
	}
	return result
}

// BuildCodebaseFoldersForFiles MUST assemble the codebase folders for files from the available context data.
// BuildCodebaseFoldersForFiles constructs and returns the codebase folders for files structure.
// [🧰repo⌨️cli💻maingo🔖types🔖codebase🛠️buildcodebasefoldersforfiles](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Codebase/d/i/BuildCodebaseFoldersForFiles)
func BuildCodebaseFoldersForFiles(ctx *CodebaseContext, checkpoint string) []CodebaseFolder {
	folderSet := make(map[string]struct{})
	fileCounts := make(map[string]int)
	lineCounts := make(map[string]int)

	for _, file := range ctx.Files {
		folder := NormalizePath(filepath.Dir(file))
		if folder == "." {
			continue
		}
		folderSet[folder] = struct{}{}
		fileCounts[folder]++
		content, err := ReadTextFileAtCheckpoint(checkpoint, file)
		if err == nil {
			lineCounts[folder] += CountLines(content)
		}
	}

	var result []CodebaseFolder
	for folder := range folderSet {
		id := ctx.GetFolderID(folder)
		parent := filepath.Dir(folder)
		var parentID *string
		if parent != "." && parent != "" {
			parentValue := parent
			parentID = &parentValue
		}
		result = append(result, CodebaseFolder{
			ID:       id,
			Path:     folder,
			URI:      ctx.FolderURI(folder),
			Name:     filepath.Base(folder),
			ParentID: parentID,
			Metrics: &FolderMetricsInternal{
				Files: fileCounts[folder],
				Lines: lineCounts[folder],
			},
		})
	}
	sort.Slice(result, func(i, j int) bool { return result[i].Path < result[j].Path })
	return result
}

// BuildCodebaseFilesForFiles MUST assemble the codebase files for files from the available context data.
// BuildCodebaseFilesForFiles constructs and returns the codebase files for files structure.
// [🧰repo⌨️cli💻maingo🔖types🔖codebase🛠️buildcodebasefilesforfiles](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Codebase/d/i/BuildCodebaseFilesForFiles)
func BuildCodebaseFilesForFiles(ctx *CodebaseContext, checkpoint string) []CodebaseFile {
	var result []CodebaseFile
	for _, file := range ctx.Files {
		id := ctx.GetFileID(file)
		var metrics *FileMetricsInternal
		content, err := ReadTextFileAtCheckpoint(checkpoint, file)
		if err == nil {
			sections := ParseSections(content, file)
			sectionCount := countSections(sections)
			lines := strings.Split(content, "\n")
			lang := GetLanguage(file)
			defCount := 0
			if lang != nil && lang.SupportsDefinitions() {
				defs := lang.ParseDefinitions(content, lines)
				defCount = len(defs)
			}
			metrics = &FileMetricsInternal{
				Sections:    sectionCount,
				Definitions: defCount,
				Lines:       len(lines),
			}
		}
		result = append(result, CodebaseFile{
			ID:      id,
			Path:    file,
			URI:     ctx.FileURI(file),
			Metrics: metrics,
		})
	}
	sort.Slice(result, func(i, j int) bool { return result[i].Path < result[j].Path })
	return result
}

// BuildCodebaseSectionsForFiles MUST assemble the codebase sections for files from the available context data.
// BuildCodebaseSectionsForFiles constructs and returns the codebase sections for files structure.
// [🧰repo⌨️cli💻maingo🔖types🔖codebase🛠️buildcodebasesectionsforfiles](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Codebase/d/i/BuildCodebaseSectionsForFiles)
func BuildCodebaseSectionsForFiles(ctx *CodebaseContext, checkpoint string) []CodebaseSection {
	var result []CodebaseSection
	for _, file := range ctx.Files {
		content, err := ReadTextFileAtCheckpoint(checkpoint, file)
		if err != nil {
			continue
		}
		sections := ParseSections(content, file)
		fileID := ctx.GetFileID(file)
		addSectionsForContent(ctx, &result, file, fileID, content, sections, "")
	}
	sort.Slice(result, func(i, j int) bool { return result[i].Path < result[j].Path })
	return result
}

func addSectionsForContent(ctx *CodebaseContext, result *[]CodebaseSection, file, fileID, content string, sections []Section, parentPath string) {
	for _, section := range sections {
		sectionPath := section.Name
		if parentPath != "" {
			sectionPath = parentPath + "#" + section.Name
		}
		id := fileID + "#" + sectionPath
		sectionContent := ""
		if section.StartIndex < len(content) && section.EndIndex <= len(content) {
			sectionContent = content[section.StartIndex:section.EndIndex]
		}
		defCount := 0
		lang := GetLanguage(file)
		if lang != nil && lang.SupportsDefinitions() {
			lines := strings.Split(sectionContent, "\n")
			defs := lang.ParseDefinitions(sectionContent, lines)
			defCount = len(defs)
		}
		*result = append(*result, CodebaseSection{
			ID:   id,
			Path: file + "#" + sectionPath,
			URI:  ctx.FileURI(file) + "#" + sectionPath,
			Metrics: &SectionMetricsInternal{
				Definitions: defCount,
				Lines:       section.EndLine - section.StartLine + 1,
			},
		})
		addSectionsForContent(ctx, result, file, fileID, content, section.Children, sectionPath)
	}
}

// BuildCodebaseDefinitionsForFiles MUST assemble the codebase definitions for files from the available context data.
// BuildCodebaseDefinitionsForFiles constructs and returns the codebase definitions for files structure.
// [🧰repo⌨️cli💻maingo🔖types🔖codebase🛠️buildcodebasedefinitionsforfiles](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Codebase/d/i/BuildCodebaseDefinitionsForFiles)
func BuildCodebaseDefinitionsForFiles(ctx *CodebaseContext, checkpoint string) []CodebaseDefinition {
	var result []CodebaseDefinition
	for _, file := range ctx.Files {
		content, err := ReadTextFileAtCheckpoint(checkpoint, file)
		if err != nil {
			continue
		}
		lang := GetLanguage(file)
		if lang == nil || !lang.SupportsDefinitions() {
			continue
		}
		lines := strings.Split(content, "\n")
		defs := lang.ParseDefinitions(content, lines)
		sections := ParseSections(content, file)
		fileID := ctx.GetFileID(file)
		for _, def := range defs {
			sectionPath := findSectionForDefinition(sections, def.Start, def.End, "")
			id := ""
			if sectionPath != "" {
				id = fileID + "#" + sectionPath + "§" + def.Name
			} else {
				id = fileID + "§" + def.Name
			}
			result = append(result, CodebaseDefinition{
				ID:   id,
				Path: id,
				URI:  ctx.FileURI(file) + "§" + def.Name,
				Metrics: &DefinitionMetricsInternal{
					Lines: def.End - def.Start + 1,
				},
			})
		}
	}
	sort.Slice(result, func(i, j int) bool { return result[i].Path < result[j].Path })
	return result
}

// ToolCodebase MUST complete the operation and return consistent results.
// ToolCodebase performs the tool codebase operation.
// [🧰repo⌨️cli💻maingo🔖types🔖codebase🛠️toolcodebase](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Codebase/d/i/ToolCodebase)
func ToolCodebase() ToolResult {
	output := NewOutput()
	ctx := NewCodebaseContext()

	ctx.LoadBundles()
	if err := ctx.LoadFiles(); err != nil {
		return toolErrorResult(err)
	}
	if err := ctx.LoadBreachs(); err != nil {
		return toolErrorResult(err)
	}
	if err := ctx.LoadTickets(); err != nil {
		return toolErrorResult(err)
	}
	ctx.LoadPolicies()

	codebase := BuildCodebase(ctx)

	output.Success(fmt.Sprintf("Codebase loaded: %d bundles, %d files, %d breachs",
		len(codebase.Bundles), len(codebase.Files), len(codebase.Breachs)))

	return ToolResult{Output: *output, Data: codebase}
}

