// FindTicketBySlug MUST return nil when no match is found.
// FindTicketBySlug searches for and returns the matching ticket by slug.
// [🧰repo⌨️cli💻maingo🔖types🔖tickets🛠️findticketbyslug](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Tickets/d/i/FindTicketBySlug)
func FindTicketBySlug(slug string) (*Ticket, error) {
	tickets, err := ListTickets(nil, nil, nil)
	if err != nil {
		return nil, err
	}
	for i := len(tickets) - 1; i >= 0; i-- {
		t := tickets[i]
		if t.Slug == slug || filepath.Base(t.Slug) == slug {
			return &t, nil
		}
	}
	return nil, fmt.Errorf("ticket not found: %s", slug)
}

// LatestTicket MUST complete the operation and return consistent results.
// LatestTicket performs the latest ticket operation.
// [🧰repo⌨️cli💻maingo🔖types🔖tickets🛠️latestticket](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Tickets/d/i/LatestTicket)
func LatestTicket() (*Ticket, error) {
	tickets, err := ListTickets(nil, nil, nil)
	if err != nil {
		return nil, err
	}
	if len(tickets) == 0 {
		return nil, fmt.Errorf("no tickets found")
	}
	sort.Slice(tickets, func(i, j int) bool {
		if tickets[i].Year != tickets[j].Year {
			return tickets[i].Year > tickets[j].Year
		}
		if tickets[i].Month != tickets[j].Month {
			return tickets[i].Month > tickets[j].Month
		}
		if tickets[i].Day != tickets[j].Day {
			return tickets[i].Day > tickets[j].Day
		}
		return tickets[i].GetDateStarted().After(tickets[j].GetDateStarted())
	})
	return &tickets[0], nil
}

func shouldContinueTicket(prompt string) bool {
	return hasTicketKeyword(prompt, "CONTINUE")
}

func shouldSkipTicket(prompt string) bool {
	return hasTicketKeyword(prompt, "NOTICKET")
}

// OpenTicket MUST complete the operation and return consistent results.
// OpenTicket performs the open ticket operation.
// [🧰repo⌨️cli💻maingo🔖types🔖tickets🛠️openticket](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Tickets/d/i/OpenTicket)
func OpenTicket(title, prompt, llm, client, draft string, noIssue bool, goal string, parent string, noManagement bool, issue string) (*Ticket, error) {
	if prompt == "" {
		prompt = title
	}
	if shouldSkipTicket(prompt) {
		return nil, nil
	}
	if shouldContinueTicket(prompt) {
		latest, err := LatestTicket()
		if err != nil {
			return nil, err
		}
		if latest.GetStatus() == TicketStatusClosed {
			return latest, ReopenTicket(latest, prompt, llm, client, draft, goal, parent, noManagement)
		}
		return latest, nil
	}
	return CreateTicket(title, prompt, llm, client, draft, noIssue, goal, parent, noManagement, issue)
}

