// FilterTicketWorkspaceFiles MUST return only entries that match the filter criteria.
// FilterTicketWorkspaceFiles returns the subset of ticket workspace files matching the criteria.
// [🧰repo⌨️cli💻maingo🔖types🔖tickets🛠️filterticketworkspacefiles](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Tickets/d/i/FilterTicketWorkspaceFiles)
func FilterTicketWorkspaceFiles(ticket *Ticket, files []string) []string {
	if ticket == nil {
		return files
	}
	if len(files) == 0 {
		return files
	}
	if ticket.FolderPath == "" {
		return files
	}
	relative := NormalizePath(ticket.FolderPath)
	if filepath.IsAbs(ticket.FolderPath) {
		relative = GetRelativePath(ticket.FolderPath)
	}
	relative = strings.TrimPrefix(relative, "./")
	if relative == "" {
		return files
	}
	filtered := make([]string, 0, len(files))
	for _, filePath := range files {
		normalized := NormalizePath(filePath)
		if filepath.IsAbs(filePath) {
			normalized = GetRelativePath(filePath)
		}
		normalized = strings.TrimPrefix(normalized, "./")
		if normalized == relative || strings.HasPrefix(normalized, relative+"/") {
			continue
		}
		filtered = append(filtered, filePath)
	}
	return filtered
}

