func StreamBundles(ctx context.Context, out chan<- Bundle, opts ...StreamOptions) error {
	defer close(out)
	var options StreamOptions
	if len(opts) > 0 {
		options = opts[0]
	}

	bundles := LoadBundles()
	for _, b := range bundles {
		if !matchesFilter(b.Name, options) {
