}

// StreamFiles MUST invoke the callback for each matching files entry.
// StreamFiles streams files entries through the callback.
// [🧰repo⌨️cli💻maingo🔖types🔖tickets🛠️streamfiles](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Tickets/d/i/StreamFiles)
func StreamFiles(ctx context.Context, scope string, out chan<- File, opts ...StreamOptions) error {
	defer close(out)
	var options StreamOptions
	if len(opts) > 0 {
		options = opts[0]
	}

	root := rootDir
	if scope != "" && scope != "compose" {
		bundles := GetTechnologies()
		matched := false
		for _, b := range bundles {
			if b.Name == scope || b.Root == scope || normalizeBundleLabel(b.Name) == scope {
				root = filepath.Join(rootDir, b.Root)
				matched = true
				break
			}
		}
		if !matched {
			parts := strings.SplitN(scope, "/", 3)
			if len(parts) == 3 {
				bundleScope := parts[0] + "/" + parts[1]
				subPath := parts[2]
				for _, b := range bundles {
					if b.Name == bundleScope || b.Root == bundleScope || normalizeBundleLabel(b.Name) == bundleScope {
						root = filepath.Join(rootDir, b.Root, subPath)
						matched = true
						break
					}
				}
			}
		}
		if !matched {
			if filepath.IsAbs(scope) {
				root = scope
			} else {
				root = filepath.Join(rootDir, scope)
			}
		}
	}

	if info, err := os.Stat(root); err == nil && !info.IsDir() {
		relPath, _ := filepath.Rel(rootDir, root)
		var bundleID *string
		if b := GetBundleByPath(relPath); b != nil {
			id := b.GetID()
			bundleID = &id
		}
		folderPath := filepath.Dir(relPath)
		var folderID *string
		if folderPath != "." {
			id := buildFolderID(folderPath, bundleID)
			folderID = &id
		}
		out <- File{
			ID:        buildFileID(relPath, bundleID),
			Path:      relPath,
			URI:       buildFileUriFromPath(relPath),
			Name:      filepath.Base(relPath),
			Extension: filepath.Ext(relPath),
			FolderID:  folderID,
			BundleID:  bundleID,
			Kind:      DeriveFileKind(filepath.Base(relPath)),
			Ignored:   isGitIgnored(root),
			Generated: IsGenerated(root),
		}
		return nil
	}

	var files []string
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if info.IsDir() {
			rel, _ := filepath.Rel(root, path)
			if rel != "." {
				if isRepoExcludedPath(path) {
					return filepath.SkipDir
				}
				if isGitIgnored(path) && !options.ShowIgnored {
					return filepath.SkipDir
				}
			}
			return nil
		}
		if isRepoExcludedPath(path) {
			return nil
		}
		if isGitIgnored(path) && !options.ShowIgnored {
			return nil
		}
		files = append(files, path)
		return nil
	})
	if err != nil {
		return err
	}

	for _, filePath := range files {
		ignored := isGitIgnored(filePath)
		generated := IsGenerated(filePath)
		kind := DeriveFileKind(filepath.Base(filePath))

		if ignored && !options.ShowIgnored {
			continue
		}
		if generated && !options.ShowGenerated {
			continue
		}

		if !shouldIncludeKind(kind, options) {
			continue
		}

		name := filepath.Base(filePath)
		if !matchesFilter(name, options) {
			continue
		}
		if !matchesQuery(filePath, options) {
			continue
		}

		relPath, _ := filepath.Rel(rootDir, filePath)
		var bundleID *string
		if b := GetBundleByPath(relPath); b != nil {
			id := b.GetID()
			bundleID = &id
		}

		folderPath := filepath.Dir(relPath)
		var folderID *string
		if folderPath != "." {
			id := buildFolderID(folderPath, bundleID)
			folderID = &id
		}

		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
			out <- File{
				ID:        buildFileID(relPath, bundleID),
				Path:      relPath,
				URI:       buildFileUriFromPath(relPath),
				Name:      filepath.Base(relPath),
				Extension: filepath.Ext(relPath),
				FolderID:  folderID,
				BundleID:  bundleID,
				Kind:      kind,
				Ignored:   ignored,
				Generated: generated,
			}
		}
	}
	return nil
}

func flattenSections(sections []Section) []Section {
	return flattenSectionsWithPrefix(sections, "")
}

func flattenSectionsWithPrefix(sections []Section, prefix string) []Section {
	var result []Section
	for _, s := range sections {
		children := s.Children
		s.Children = nil
		if prefix != "" {
			s.Path = prefix + "#" + s.Name
		} else {
			s.Path = s.Name
		}
		result = append(result, s)
		result = append(result, flattenSectionsWithPrefix(children, s.Path)...)
	}
	return result
}

func hydrateSectionMetadata(s *Section, filePath string, prefix string) {
	s.FilePath = filePath
	s.Path = prefix
	for i := range s.Children {
		childPath := prefix + "#" + s.Children[i].Name
		hydrateSectionMetadata(&s.Children[i], filePath, childPath)
	}
}

// StreamSections MUST invoke the callback for each matching sections entry.
// StreamSections streams sections entries through the callback.
// [🧰repo⌨️cli💻maingo🔖types🔖tickets🛠️streamsections](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Tickets/d/i/StreamSections)
func StreamSections(ctx context.Context, scope string, out chan<- Section, opts ...StreamOptions) error {
	defer close(out)
	var options StreamOptions
	if len(opts) > 0 {
		options = opts[0]
	}

	filesOpts := options
	filesOpts.Filter = ""
	filesOpts.Regex = false

	fileChan := make(chan File)
	go func() {
		StreamFiles(ctx, scope, fileChan, filesOpts)
	}()

	for f := range fileChan {
		fullPath := f.Path
		if !filepath.IsAbs(fullPath) {
			fullPath = filepath.Join(rootDir, fullPath)
		}
		content, err := ReadTextFile(fullPath)
		if err != nil {
			continue
		}
		sections := ParseSections(content, f.Path)
		if options.Filter != "" || options.Regex {
			flatSections := flattenSections(sections)
			for _, s := range flatSections {
				s.FilePath = f.Path
				if !matchesFilter(s.Name, options) {
					continue
				}
				if !matchesQuery(s.Name+" "+s.FilePath, options) {
					continue
				}

				select {
				case <-ctx.Done():
					return ctx.Err()
				default:
					out <- s
				}
			}
		} else {
			for i := range sections {
				hydrateSectionMetadata(&sections[i], f.Path, sections[i].Name)
				select {
				case <-ctx.Done():
					return ctx.Err()
				default:
					out <- sections[i]
				}
			}
		}
	}
	return nil
}

