// [🧰repo⌨️cli💻maingo🔖types🔖graphqlexecutor🛠️execute](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/GraphQL%20Executor/d/i/Execute)
func (e *Executor) Execute(ctx context.Context, query string, variables map[string]interface{}) (interface{}, error) {
	result := graphql.Do(graphql.Params{
		Context:        ctx,
		Schema:         e.schema,
		RequestString:  query,
		VariableValues: variables,
	})
