	parseFilterInput := func(args map[string]interface{}) *FilterInput {
		filterArg, ok := args["filter"]
		if !ok || filterArg == nil {
			return nil
		}
		filterMap, ok := filterArg.(map[string]interface{})
		if !ok {
			return nil
		}
		input := &FilterInput{}
		if v, ok := filterMap["filter"].(string); ok {
