// Node MUST return a non-nil error when the operation fails.
// Node performs the node operation on the query resolver.
// [🧰repo⌨️cli💻maingo🔖types🔖queryresolvers🛠️node](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Query%20Resolvers/d/i/Node)
func (r *queryResolver) Node(ctx context.Context, id string) (Node, error) {

	cleanID := strings.ReplaceAll(id, "\uFE0E", "")
	cleanID = strings.ReplaceAll(cleanID, "\uFE0F", "")

	if cleanID == "" {
		return r.Repo(ctx)
	}

	stripPrefix := func(s, emoji string) (string, bool) {
		p := strings.ReplaceAll(emoji, "\uFE0F", "")
		p = strings.ReplaceAll(p, "\uFE0E", "")
		if p == "" {
			return s, false
		}
		if strings.HasPrefix(s, p) {
			return strings.TrimPrefix(s, p), true
		}
		return s, false
	}
	findEmoji := func(s string, emojis []string) (before string, after string, found bool) {
		for _, e := range emojis {
			ne := strings.ReplaceAll(e, "\uFE0F", "")
			ne = strings.ReplaceAll(ne, "\uFE0E", "")
			if ne == "" {
				continue
			}
			idx := strings.Index(s, ne)
			if idx >= 0 {
				return s[:idx], s[idx+len(ne):], true
			}
		}
		return s, "", false
	}

	technologyEmojis := []string{EmojiTechnologyUser, EmojiTechnologyInfra, EmojiTechnologyResearch, EmojiTechnologyMono}
	bundleEmojis := []string{EmojiBundleLibrary, EmojiBundleSchema, EmojiBundleBinary, EmojiBundleUI, EmojiBundleExample, EmojiBundleSite, EmojiBundleAssets, EmojiBundleRepo}
	for _, pe := range technologyEmojis {
		if rest, ok := stripPrefix(cleanID, pe); ok {
			if technologyVal, bundleVal, found := findEmoji(rest, bundleEmojis); found {
				return r.Bundle(ctx, technologyVal+"/"+bundleVal)
			}
			return &Technology{Name: rest}, nil
		}
	}

	folderEmojis := []string{EmojiFolderOrg, EmojiFolderRequired}
	for _, fe := range folderEmojis {
		if rest, ok := stripPrefix(cleanID, fe); ok {
			return r.Folder(ctx, rest)
		}
	}

	fileEmojis := []string{EmojiFileCode, EmojiFileLab, EmojiFileScript, EmojiFileDocs, EmojiFileConfig, EmojiFileResource, EmojiFileLicense}
	for _, fe := range fileEmojis {
		if rest, ok := stripPrefix(cleanID, fe); ok {
			return r.File(ctx, rest)
		}
	}

	defEmojis := []string{EmojiDefinitionImpl, EmojiDefinitionInterface, EmojiDefinitionConstant, EmojiDefinitionTest}
	for _, de := range defEmojis {
		if rest, ok := stripPrefix(cleanID, de); ok {
			return &Definition{ID: rest}, nil
		}
	}

	if rest, ok := stripPrefix(cleanID, EmojiTicket); ok {
		clean := strings.SplitN(rest, "?", 2)[0]
		if len(clean) >= 8 {
			y, _ := strconv.Atoi(clean[0:4])
			m, _ := strconv.Atoi(clean[4:6])
			d, _ := strconv.Atoi(clean[6:8])
			slug := clean[8:]
			return r.Ticket(ctx, y, m, d, slug)
		}
	}

	if rest, ok := stripPrefix(cleanID, EmojiGoal); ok {
		return &Goal{ID: rest, Title: rest}, nil
	}

	if rest, ok := stripPrefix(cleanID, EmojiPolicy); ok {
		return r.Policy(ctx, rest)
	}

	if rest, ok := stripPrefix(cleanID, EmojiContributor); ok {
		return r.Contributor(ctx, rest)
	}

	if rest, ok := stripPrefix(cleanID, EmojiCheckpoint); ok {
		return &Checkpoint{SHA: rest}, nil
	}

	if strings.HasPrefix(id, "repo:") {
		return r.Repo(ctx)
	}
	if strings.HasPrefix(id, "technology:") {
		return &Technology{Name: strings.TrimPrefix(id, "technology:")}, nil
	}
	if strings.HasPrefix(id, "bundle:") {
		return r.Bundle(ctx, strings.TrimPrefix(id, "bundle:"))
	}
	if strings.HasPrefix(id, "folder:") {
		return r.Folder(ctx, strings.TrimPrefix(id, "folder:"))
	}
	if strings.HasPrefix(id, "file:") {
		return r.File(ctx, strings.TrimPrefix(id, "file:"))
	}
	if strings.HasPrefix(id, "contributor:") {
		return r.Contributor(ctx, strings.TrimPrefix(id, "contributor:"))
	}
	if strings.HasPrefix(id, "policy:") {
		return r.Policy(ctx, strings.TrimPrefix(id, "policy:"))
	}
	if strings.HasPrefix(id, "breach:") {

		return nil, fmt.Errorf("resolving breach by ID not implemented")
	}
	if strings.HasPrefix(id, "ticket:") {
		slugID := strings.TrimPrefix(id, "ticket:")
		parts := strings.Split(slugID, "/")
		if len(parts) == 4 {
			y, _ := strconv.Atoi(parts[0])
			m, _ := strconv.Atoi(parts[1])
			d, _ := strconv.Atoi(parts[2])
			return r.Ticket(ctx, y, m, d, parts[3])
		}
	}
	if strings.HasPrefix(id, "checkpoint:") {

		return &Checkpoint{SHA: strings.TrimPrefix(id, "checkpoint:")}, nil
	}
	if strings.HasPrefix(id, "goal:") {

		slug := strings.TrimPrefix(id, "goal:")

		return &Goal{ID: slug, Title: slug}, nil
	}

	if strings.HasPrefix(id, "section:") {

		full := strings.TrimPrefix(id, "section:")
		parts := strings.SplitN(full, "#", 2)
		if len(parts) == 2 {
			f, err := r.File(ctx, parts[0])
			if err == nil && f != nil {

				return nil, fmt.Errorf("resolving section by ID not implemented")
			}
		}
	}
	if strings.HasPrefix(id, "definition:") {
		return nil, fmt.Errorf("resolving definition by ID not implemented")
	}

	return nil, fmt.Errorf("invalid node id format: %s", id)
}

// Repo MUST return a non-nil error when the operation fails.
// Repo performs the repo operation on the query resolver.
// [🧰repo⌨️cli💻maingo🔖types🔖queryresolvers🛠️repo](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Query%20Resolvers/d/i/Repo)
func (r *queryResolver) Repo(ctx context.Context) (*Repo, error) {
	technologies, _ := r.Technologies(ctx, nil)
	bundles, _ := r.Bundles(ctx, &FilterInput{})

	var technologyValues []Technology
	for _, p := range technologies {
		technologyValues = append(technologyValues, *p)
	}
	var bundleValues []Bundle
	for _, b := range bundles {
		bundleValues = append(bundleValues, *b)
	}

	return &Repo{
		ID:           "repo:compose",
		Name:         "compose",
		Path:         r.RootDir,
		Technologies: technologyValues,
		Bundles:      bundleValues,
	}, nil
}

// Technologies MUST return a non-nil error when the operation fails.
// Technologies performs the technologies operation on the query resolver.
// [🧰repo⌨️cli💻maingo🔖types🔖queryresolvers🛠️technologies](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Query%20Resolvers/d/i/Technologies)
func (r *queryResolver) Technologies(ctx context.Context, filter *FilterInput) ([]*Technology, error) {
	allBundles, err := r.Bundles(ctx, &FilterInput{})
	if err != nil {
		return nil, err
	}
	technologyMap := make(map[string]*Technology)
	for _, b := range allBundles {
		name := normalizeBundleLabel(b.Name)
		parts := strings.Split(name, "/")
		projName := "compose"
		if len(parts) > 1 && strings.HasPrefix(parts[0], "@") {
			projName = strings.TrimPrefix(parts[0], "@")
		} else if strings.HasPrefix(name, "@") {
			if name == "compose" {
				projName = "compose"
			}
			if name == "@coda" {
				projName = "coda"
			}
		}

		if _, ok := technologyMap[projName]; !ok {
			kind := TechnologyKindUser
			if projName == "repo" {
				kind = TechnologyKindInfrastructure
			}
			technologyMap[projName] = &Technology{
				Name:    projName,
				Kind:    kind,
				Root:    r.RootDir,
				Bundles: []Bundle{},
			}
		}
		technologyMap[projName].Bundles = append(technologyMap[projName].Bundles, *b)
	}

	var results []*Technology
	for _, p := range technologyMap {
		if filter != nil {
			opts := filter.ToStreamOptions()
			if !matchesFilter(p.Name, opts) && !matchesFilter(p.GetID(), opts) {
				continue
			}
		}
		results = append(results, p)
	}
	sort.Slice(results, func(i, j int) bool {
		return results[i].Name < results[j].Name
	})
	return results, nil
}

