func (r *queryResolver) Policies(ctx context.Context, filter *FilterInput) ([]*Policy, error) {
	if r.Ctx != nil {
		opts := filter.ToStreamOptions()
		policyChan := make(chan PolicyDef)
		go StreamPolicies(ctx, policyChan, opts)
		var policies []*Policy
		for p := range policyChan {
			desc := p.Description
			var vks []*StatuteMeta
			for _, k := range p.AllKinds() {
				meta := k.Info()
				meta.PolicyID = p.ID
				vks = append(vks, &meta)
			}
			policies = append(policies, &Policy{
				ID:          p.ID,
				Name:        p.Name,
				Description: &desc,
				Scopes:      p.Scopes,
				Groups:      p.Groups,
				Statutes:    vks,
			})
		}
		return policies, nil
	}
	return []*Policy{}, nil
}

