// [🧰repo⌨️cli💻maingo🔖types🔖cli🔖missingutilities](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Missing%20Utilities)
// Utility functions that are missing from the main codebase.

// ScopeToFiles MUST return a non-nil error when the operation fails.
// ScopeToFiles performs the scope to files operation.
// [🧰repo⌨️cli💻maingo🔖types🔖cli🔖missingutilities🛠️scopetofiles](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Missing%20Utilities/d/i/ScopeToFiles)
func ScopeToFiles(scope Scope, bundles []Bundle) ([]string, error) {
	ignorePatterns := []string{"**/node_modules/**", "**/.venv/**"}
	var files []string
	var err error
	switch scope.Kind {
	case ScopeRepo:
		files, err = globByExtension(rootDir, "**/*", []string{"ts", "tsx", "py", "cs", "go", "rs"}, ignorePatterns, true)
	case ScopeTechnology:
		for _, proj := range bundles {
			if proj.Name == scope.TechnologyName {
				files, err = globByExtension(rootDir, proj.Root+"/**/*", []string{"ts", "tsx", "py", "cs", "go", "rs"}, ignorePatterns, true)
				break
			}
		}
	case ScopeFolder:
		if scope.FilePath != "" {
			files, err = globByExtension(rootDir, scope.FilePath+"**/*", []string{"ts", "tsx", "py", "cs", "go", "rs"}, ignorePatterns, true)
		}
	case ScopeFile, ScopeSection, ScopeDefinition:
		if scope.FilePath != "" {
			files = []string{scope.FilePath}
		}
	}
	if err != nil {
		return nil, err
	}
	files = filterConsideredFiles(files)
	files = filterGitIgnored(files)
	return files, nil
}

func normalizeRepoPath(path string) string {
	normalized := NormalizePath(path)
	if filepath.IsAbs(path) {
		normalized = GetRelativePath(path)
	}
	normalized = strings.TrimPrefix(normalized, "./")
	return normalized
}

func isRepoExcludedPath(path string) bool {
	normalized := normalizeRepoPath(path)
	if normalized == "" {
		return false
	}
	if normalized == ".repo" || strings.HasPrefix(normalized, ".repo/") {
		return true
	}
	if normalized == "assets/repo" || strings.HasPrefix(normalized, "assets/repo/") || strings.Contains(normalized, "/assets/repo/") {
		return true
	}
	if normalized == ".git" || strings.HasPrefix(normalized, ".git/") {
		return true
	}
	if normalized == "node_modules" || strings.HasPrefix(normalized, "node_modules/") {
		return true
	}
	base := filepath.Base(normalized)
	if strings.HasSuffix(base, ".Designer.cs") {
		return true
	}
	if strings.Contains(normalized, "/codegen/") {
		return true
	}
	return false
}

func filterConsideredFiles(files []string) []string {
	if len(files) == 0 {
		return files
	}
	filtered := make([]string, 0, len(files))
	for _, filePath := range files {
		if isRepoExcludedPath(filePath) {
			continue
		}
		if isGitIgnored(filePath) {
			continue
		}
		filtered = append(filtered, filePath)
	}
	return filtered
}

// GitIndexRef is the git ref for the staging index. Used for unstaged-only diffs (index vs working tree).
// Requirements: ticket close and interaction finish use only unstaged diffs; git diff runs without tree-ish for index vs working tree.
// [🧰repo⌨️cli💻maingo🔖types🔖cli🔖missingutilities🪨gitindexref](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Missing%20Utilities/d/i/GitIndexRef)
const GitIndexRef = ":0"

// ComputeTicketFiles MUST return the computed result deterministically.
// ComputeTicketFiles computes and returns the ticket files.
// Uses unstaged diffs only (index vs working tree) for complete, current working state.
// [🧰repo⌨️cli💻maingo🔖types🔖cli🔖missingutilities🛠️computeticketfiles](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Missing%20Utilities/d/i/ComputeTicketFiles)
func ComputeTicketFiles(ticket *Ticket, files []string) (*TicketDiffs, error) {
	files = normalizeTicketFileInputs(files)
	files = FilterTicketWorkspaceFiles(ticket, files)
	files = filterConsideredFiles(files)
	files = filterGitIgnored(files)
	if len(files) == 0 {
		return nil, fmt.Errorf("at least one file is required")
	}
	baseRef := GitIndexRef
	diffStatuses, err := GetGitDiffStatus(baseRef, "", files)
	if err != nil {
		return nil, err
	}
	diffLines, err := GetGitDiffLines(baseRef, "", files)
	if err != nil {
		return nil, err
	}

	currentFiles := make(map[string]struct{})
	baseFiles := make(map[string]struct{})
	for _, file := range files {
		currentFiles[file] = struct{}{}
		baseFiles[file] = struct{}{}
	}
	for _, status := range diffStatuses {
		if status.To != "" {
			currentFiles[status.To] = struct{}{}
		}
		if status.From != "" {
			baseFiles[status.From] = struct{}{}
		}
	}
	var currentFileList []string
	for file := range currentFiles {
		currentFileList = append(currentFileList, file)
	}
	var baseFileList []string
	for file := range baseFiles {
