// GitDiffStatus holds the data fields for a git diff status record.
// [🧰repo⌨️cli💻maingo🔖types🔖cli🔖missingutilities✂️gitdiffstatus](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Missing%20Utilities/d/i/GitDiffStatus)
type GitDiffStatus struct {
	Status string
	From   string
	To     string
}

// GetGitDiffStatus MUST retrieve the requested value or return an error.
// GetGitDiffStatus retrieves and returns the git diff status.
// [🧰repo⌨️cli💻maingo🔖types🔖cli🔖missingutilities🛠️getgitdiffstatus](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Missing%20Utilities/d/i/GetGitDiffStatus)
func GetGitDiffStatus(baseCheckpoint, headCheckpoint string, paths []string) ([]GitDiffStatus, error) {
	if baseCheckpoint == "" {
		return nil, fmt.Errorf("base checkpoint or GitIndexRef is required")
	}
	args := []string{"diff", "--name-status", "-M"}
	if baseCheckpoint != GitIndexRef {
		args = append(args, baseCheckpoint)
		if headCheckpoint != "" {
			args = append(args, headCheckpoint)
		}
	}
	if len(paths) > 0 {
		args = append(args, "--")
		args = append(args, paths...)
	}
	stdout, stderr, exitCode := ExecCommand("git", args, "")
	if exitCode != 0 {
		return nil, fmt.Errorf("git diff status failed: %s", strings.TrimSpace(stderr))
	}
	var results []GitDiffStatus
	for _, line := range strings.Split(strings.TrimSpace(stdout), "\n") {
		if line == "" {
			continue
		}
		parts := strings.Split(line, "\t")
		if len(parts) < 2 {
			continue
		}
		status := strings.TrimSpace(parts[0])
		if strings.HasPrefix(status, "R") && len(parts) >= 3 {
			results = append(results, GitDiffStatus{Status: "renamed", From: parts[1], To: parts[2]})
			continue
		}
		file := parts[1]
		switch status {
		case "A":
			results = append(results, GitDiffStatus{Status: "added", To: file})
		case "D":
			results = append(results, GitDiffStatus{Status: "deleted", From: file})
		case "M":
			results = append(results, GitDiffStatus{Status: "modified", To: file})
		default:
			results = append(results, GitDiffStatus{Status: "modified", To: file})
		}
	}
	return results, nil
}

// GetFolderChildren MUST retrieve the requested value or return an error.
// GetFolderChildren retrieves and returns the folder children.
// [🧰repo⌨️cli💻maingo🔖types🔖cli🔖missingutilities🛠️getfolderchildren](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Missing%20Utilities/d/i/GetFolderChildren)
func GetFolderChildren(folderPath string, bundleID *string) ([]*Folder, error) {
	absPath := filepath.Join(rootDir, folderPath)
	entries, err := os.ReadDir(absPath)
	if err != nil {
		return []*Folder{}, nil
	}
	type candidate struct {
		name    string
		relPath string
	}
	var candidates []candidate
	var relPaths []string
	for _, entry := range entries {
		if entry.IsDir() {
			if strings.HasPrefix(entry.Name(), ".") && entry.Name() != ".repo" {
				continue
			}
			if entry.Name() == "node_modules" || entry.Name() == "bin" || entry.Name() == "obj" {
				continue
			}
			relPath := NormalizePath(filepath.Join(folderPath, entry.Name()))
			candidates = append(candidates, candidate{name: entry.Name(), relPath: relPath})
			relPaths = append(relPaths, relPath)
		}
	}
	ignored := GetGitIgnoredSet(relPaths)
	var children []*Folder
	for _, c := range candidates {
		if ignored[c.relPath] || ignored[c.relPath+"/"] {
			continue
		}
		child := &Folder{
			ID:       buildFolderID(c.relPath, bundleID),
			Path:     c.relPath,
			URI:      fmt.Sprintf("file://%s/%s", rootDir, c.relPath),
			Name:     c.name,
			BundleID: bundleID,
		}
		children = append(children, child)
	}
	return children, nil
}

