			URI:       fmt.Sprintf("file://%s/%s", rootDir, relPath),
			Name:      filepath.Base(relPath),
			Extension: filepath.Ext(relPath),
			FolderID:  folderID,
			BundleID:  bundleID,
		})
	}
	return files, nil
