func ListContributors() ([]Contributor, error) {
	var result []Contributor
	dir := filepath.Join(GetRepoMetaDir(), "🧑‍💻")
	if !FileExists(dir) {
		return []Contributor{{Alias: "unknown", Github: "unknown", Name: "Unknown"}}, nil
	}
	entries, _ := os.ReadDir(dir)
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		p := filepath.Join(dir, e.Name(), "contributor.json")
		if !FileExists(p) {
			continue
		}
		content, _ := ReadTextFile(p)
		var c Contributor
		json.Unmarshal([]byte(content), &c)
		if c.Alias == "" {
			c.Alias = e.Name()
		}
		if c.Github == "" {
			c.Github = e.Name()
		}
		result = append(result, c)
	}
	return result, nil
}

// StreamContributors MUST invoke the callback for each matching contributors entry.
// StreamContributors streams contributors entries through the callback.
// [🧰repo⌨️cli💻maingo🔖types🔖cli🛠️streamcontributors](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/d/i/StreamContributors)
func StreamContributors(ctx context.Context, out chan<- Contributor, opts ...StreamOptions) error {
	defer close(out)
	var options StreamOptions
	if len(opts) > 0 {
		options = opts[0]
	}

	contributors, err := ListContributors()
	if err != nil {
		return err
	}

	for _, c := range contributors {
		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
			if !matchesFilter(c.Alias, options) && !matchesFilter(c.Name, options) {
				continue
			}
			if !matchesQuery(c.Alias+" "+c.Name, options) {
				continue
			}
			if len(options.IncludeContributors) > 0 {
				found := false
				for _, id := range options.IncludeContributors {
					if c.Alias == id || c.Name == id {
						found = true
						break
					}
				}
				if !found {
					continue
				}
			}
			if len(options.ExcludeContributors) > 0 {
				excluded := false
				for _, id := range options.ExcludeContributors {
					if c.Alias == id || c.Name == id {
						excluded = true
						break
					}
				}
				if excluded {
					continue
				}
			}
			out <- c
		}
	}
	return nil
}

