// [🧰repo⌨️cli💻maingo🔖types🔖cli🔖goals🛠️streamcheckpoints](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Goals/d/i/StreamCheckpoints)
func StreamCheckpoints(ctx context.Context, limit *int, out chan<- Checkpoint, opts ...StreamOptions) error {
