func SaveGoal(goal Goal) error {
	dir := GetRepoGoalsDir()
	path := filepath.Join(dir, filepath.FromSlash(goal.ID), "goal.json")
	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
