func truncateANSI(s string, maxVisible int) string {
	if maxVisible <= 0 {
		return s
	}
	visible := 0
	for i := 0; i < len(s); {
		if s[i] == 0x1b {
			j := i + 1
			for j < len(s) && s[j] != 'm' {
				j++
			}
			if j < len(s) {
				j++
			}
			i = j
			continue
		}
		_, size := utf8.DecodeRuneInString(s[i:])
		if size <= 0 {
			break
		}
		i += size
		visible++
		if visible > maxVisible {
			break
		}
	}
	if visible <= maxVisible {
		return s
	}
	if maxVisible <= 3 {
		maxVisible = 3
	}
	limit := maxVisible - 3
	var b strings.Builder
	visible = 0
	for i := 0; i < len(s); {
		if s[i] == 0x1b {
			j := i + 1
			for j < len(s) && s[j] != 'm' {
				j++
			}
			if j < len(s) {
				j++
			}
			b.WriteString(s[i:j])
			i = j
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		if size <= 0 {
			break
		}
		if visible >= limit {
			break
		}
		b.WriteRune(r)
		visible++
		i += size
	}
	b.WriteString("...")
	b.WriteString("\x1b[0m")
	return b.String()
}

