		}
		if !foundBeta {
			t.Errorf("expected to find TestBeta in IDs, got %v", ids)
		}
		// helperNotATest should NOT be included
		for _, id := range ids {
			if strings.Contains(id, "helpernotatest") {
				t.Errorf("expected helperNotATest to be excluded, but found in IDs: %s", id)
