			if strings.Contains(id, "testfoo") {
				foundFoo = true
			}
			if strings.Contains(id, "testbar") {
				foundBar = true
			}
		}
		if !foundFoo {
			t.Errorf("expected test_foo in IDs, got %v", ids)
		}
		if !foundBar {
			t.Errorf("expected test_bar in IDs, got %v", ids)
		}
