		input := json.RawMessage(`{"tool_input":{"query":"**/*.ts"}}`)
		pages, ranges := extractSearchFromInput(input, "")
		if len(pages) != 0 {
			t.Errorf("expected no webpages, got %v", pages)
		}
		if len(ranges) != 0 {
			t.Errorf("expected no ranges, got %v", ranges)
		}
	})
