	absPrefix := filepath.ToSlash(tmpDir)
	for _, def := range res.Definitions {
		if strings.Contains(def.ID, absPrefix) {
			t.Errorf("definition ID %q contains absolute path %q", def.ID, absPrefix)
		}
	}
}

