// deriveRepoOpFromMCPTool maps a mcp__repo__* tool name to a repo operation name.
// Returns empty string if the tool is not a repo tool.
// deriveRepoOpFromMCPTool MUST perform the deriveRepoOpFromMCPTool operation.
// [🧰repo⌨️cli💻maingo🔖types🔖cli🔖hooks🛠️deriveRepoOpFromMCPTool](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Hooks/d/i/deriveRepoOpFromMCPTool)
func deriveRepoOpFromMCPTool(toolName string) string {
	const prefix = "mcp__repo__"
	if !strings.HasPrefix(toolName, prefix) {
		return ""
	}
	op := strings.TrimPrefix(toolName, prefix)
	op = strings.ReplaceAll(op, "_", ".")
	return op
}

// deriveRepoOpFromCLICommand maps a repo CLI command to a repo operation name.
// Returns empty string if the command is not a repo CLI operation.
// deriveRepoOpFromCLICommand MUST perform the deriveRepoOpFromCLICommand operation.
// [🧰repo⌨️cli💻maingo🔖types🔖cli🔖hooks🛠️deriveRepoOpFromCLICommand](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Hooks/d/i/deriveRepoOpFromCLICommand)
func deriveRepoOpFromCLICommand(command string) string {
	parts := strings.Fields(command)
	// Find the "cli" binary segment and extract subcommands after it
	cliIdx := -1
	for i, p := range parts {
		base := filepath.Base(p)
		if base == "cli" || base == "cli.exe" {
			cliIdx = i
			break
		}
	}
	if cliIdx < 0 {
		return ""
	}
	subs := parts[cliIdx+1:]
	// Filter out flags (starting with -)
	var ops []string
	for _, s := range subs {
		if strings.HasPrefix(s, "-") {
			break
		}
		ops = append(ops, s)
		if len(ops) == 2 {
			break
		}
	}
	if len(ops) == 0 {
		return ""
	}
	return strings.Join(ops, ".")
}

// logRepoOperationHook writes a derived repo-specific log entry when a repo
// MCP tool or CLI command is detected in the hook context.
// logRepoOperationHook MUST perform the logRepoOperationHook operation.
// [🧰repo⌨️cli💻maingo🔖types🔖cli🔖hooks🛠️logRepoOperationHook](repo://p/i/repo/b/b/cli/f/main.go/s/Types/s/Cli/s/Hooks/d/i/logRepoOperationHook)
func logRepoOperationHook(hctx HookContext, result HookResult, logDir string, now time.Time, sessionID string) {
	var op string
	var isStarting bool
	var toolInput json.RawMessage

	switch res := result.(type) {
	case HookResultAgentToolStarting:
		op = deriveRepoOpFromMCPTool(res.Name)
		isStarting = true
		toolInput = res.Input
	case HookResultAgentToolEnded:
		op = deriveRepoOpFromMCPTool(res.Name)
		isStarting = false
		toolInput = res.Input
	case HookResultAgentToolTerminalStarting:
		op = deriveRepoOpFromCLICommand(res.Command)
		isStarting = true
	case HookResultAgentToolTerminalEnded:
		op = deriveRepoOpFromCLICommand(res.Command)
		isStarting = false
	}

	if op == "" {
		return
	}

	var suffix string
	if isStarting {
		suffix = ".starting"
	} else {
		suffix = ".ended"
	}
	kind := "repo." + op + suffix

	resultData, _ := json.Marshal(result)
	var eventMap map[string]interface{}
	json.Unmarshal(resultData, &eventMap)
	if eventMap == nil {
		eventMap = map[string]interface{}{}
	}
	delete(eventMap, "allowed")
	eventMap["kind"] = kind
	if toolInput != nil {
		eventMap["input"] = toolInput
	}
	eventMap["contributor"] = contributorGithubToComposeID(GetGitAuthorAlias())
	resolveEventIDs(eventMap)
	data, err := json.Marshal(eventMap)
	if err != nil {
		return
	}

	var logResponse HookLogResponse
	logResponse.Allowed = result.IsAllowed()
	native := HookLogNative{Event: hctx.Input}
	entry := HookLogEntry{Native: native, Event: data, Response: logResponse}

	_ = now
	appendSessionEvent(logDir, sessionID, entry, SessionMeta{
		ID:          sessionID,
		URI:         GetArtifactURI("session", map[string]interface{}{"uuid": sessionID}),
		Contributor: contributorGithubToComposeID(GetGitAuthorAlias()),
		Client:      hctx.Client,
		Second:      hctx.Second,
		Transcript:  extractTranscriptFromInput(hctx.Input),
	})
}

